using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Drawing;
using System.Drawing.Imaging;
using System.Diagnostics;
using System.Collections.Generic;
using System.Net.WebSockets;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
public static class UlanziRecorderBridge {
 public const string PluginId="com.lucca.phonedeck.recording";
 public static string Image(RecorderState state){using(var bitmap=new Bitmap(144,144))using(var g=Graphics.FromImage(bitmap)){g.Clear(state.IsRecording?Color.FromArgb(155,26,42):Color.FromArgb(23,30,40));g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;using(var brush=new SolidBrush(state.IsRecording?Color.White:Color.FromArgb(30,186,132)))g.FillEllipse(brush,56,20,32,32);string title=state.IsRecording?"REC":state.Phase=="starting"?"INICIANDO":state.Phase=="saving"?"SALVANDO":state.Phase=="error"?"ERRO":state.Phase=="unknown"?"VERIFICAR":"GRAVAR";using(var font=new Font("Segoe UI",state.IsRecording?22:15,FontStyle.Bold))using(var brush=new SolidBrush(Color.White))using(var align=new StringFormat{Alignment=StringAlignment.Center}){g.DrawString(title,font,brush,new RectangleF(2,62,140,35),align);if(state.IsRecording)g.DrawString(state.Elapsed,font,brush,new RectangleF(2,99,140,35),align);}using(var memory=new MemoryStream()){bitmap.Save(memory,ImageFormat.Png);return "data:image/png;base64,"+Convert.ToBase64String(memory.ToArray());}}}
 public static Dictionary<string,object> Packet(string uuid,string key,string actionId,RecorderState state){return new Dictionary<string,object>{{"cmd","state"},{"uuid",PluginId},{"key",key},{"actionid",actionId},{"param",new{statelist=new[]{new{uuid=uuid,key=key,actionid=actionId,type=1,data=Image(state),textData="",showtext=false}}}}};}
 public static void Run(string[] args){string host=args.Length>1?args[1]:"127.0.0.1";int port=3906;if(args.Length>2&&!Int32.TryParse(args[2],out port))return;if(host!="127.0.0.1"&&host!="localhost"||port<1||port>65535)return;string root=AppDomain.CurrentDomain.BaseDirectory;
  bool first;using(var mutex=new Mutex(true,"Local\\PhoneDeck.UlanziRecorderBridge",out first)){if(!first)return;while(true){try{Connect(host,port,root);}catch(Exception e){try{File.WriteAllText(Path.Combine(root,"ulanzi-recorder-bridge.local.txt"),"Disconnected: "+e.GetBaseException().Message);}catch{}}Thread.Sleep(2000);}}
 }
 static void Send(ClientWebSocket socket,object data){byte[] bytes=Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(data));using(var cancel=new CancellationTokenSource(3000))socket.SendAsync(new ArraySegment<byte>(bytes),WebSocketMessageType.Text,true,cancel.Token).GetAwaiter().GetResult();}
 static string Key(Dictionary<string,object> row){return Convert.ToString(row["uuid"])+"|"+Convert.ToString(row["key"])+"|"+Convert.ToString(row["actionid"]);}
 static void Connect(string host,int port,string root){using(var socket=new ClientWebSocket()){using(var deadline=new CancellationTokenSource(5000))socket.ConnectAsync(new Uri("ws://"+host+":"+port),deadline.Token).GetAwaiter().GetResult();Send(socket,new{code=0,cmd="connected",uuid=PluginId});File.WriteAllText(Path.Combine(root,"ulanzi-recorder-bridge.local.txt"),"Connected; plugin="+PluginId+"; no capture started");var contexts=new Dictionary<string,Dictionary<string,object>>();var clicks=new Dictionary<string,DateTime>();byte[] buffer=new byte[65536];Task<WebSocketReceiveResult> pending=null;var message=new MemoryStream();DateTime last=DateTime.MinValue;
  while(socket.State==WebSocketState.Open){if(pending==null)pending=socket.ReceiveAsync(new ArraySegment<byte>(buffer),CancellationToken.None);if(pending.Wait(100)){var received=pending.Result;pending=null;if(received.MessageType==WebSocketMessageType.Close)return;message.Write(buffer,0,received.Count);if(message.Length>1048576)throw new IOException("Ulanzi message too large");if(received.EndOfMessage){var row=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(message.ToArray()));message.SetLength(0);string cmd=row.ContainsKey("cmd")?Convert.ToString(row["cmd"]):"";bool response=row.ContainsKey("code")&&(!row.ContainsKey("cmdType")||Convert.ToString(row["cmdType"])!="REQUEST");if(!response&&row.ContainsKey("uuid")&&row.ContainsKey("key")&&row.ContainsKey("actionid")){string uuid=Convert.ToString(row["uuid"]);if(uuid==PluginId+".screen"||uuid==PluginId+".phone"){if(row.ContainsKey("cmdType")&&Convert.ToString(row["cmdType"])=="REQUEST"){var ack=new Dictionary<string,object>(row);ack["code"]=0;Send(socket,ack);}string key=Key(row);contexts[key]=row;File.WriteAllText(Path.Combine(root,"ulanzi-recorder-bridge.local.txt"),"Connected; contexts="+contexts.Count);if(cmd=="clear"){contexts.Remove(key);}else if(cmd=="run"){if(!clicks.ContainsKey(key)||(DateTime.UtcNow-clicks[key]).TotalMilliseconds>1500){clicks[key]=DateTime.UtcNow;string target=Path.Combine(root,uuid.EndsWith(".screen")?"TradeRecorder.exe":"PhoneDeck.exe");if(File.Exists(target))Process.Start(new ProcessStartInfo(target,uuid.EndsWith(".phone")?"--record-panel":""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=root});}}}}}}
   if((DateTime.UtcNow-last).TotalMilliseconds>=500){foreach(var context in contexts.Values.ToArray()){string uuid=Convert.ToString(context["uuid"]);var state=uuid.EndsWith(".screen")?RecordingStatus.Screen(root):RecordingStatus.Read(ConversationRecorder.Folder);Send(socket,Packet(uuid,Convert.ToString(context["key"]),Convert.ToString(context["actionid"]),state));}last=DateTime.UtcNow;}
  }
 }}
}